<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Models\Book; use App\Models\Category; use Illuminate\Http\Request; use App\Http\Resources\BookResource;
class PublicCatalogController extends Controller { public function books(Request $r) { $d=$r->validate(['search'=>['nullable','string','max:100'],'category'=>['nullable','string'],'sort'=>['nullable','in:newest,price_asc,price_desc,bestseller,promo'],'per_page'=>['nullable','integer','min:1','max:50']]); $q=Book::where('is_active',true)->with('category')->withAvg(['reviews' => fn($q) => $q->where('status', 'approved')], 'rating'); if($s=$d['search']??null)$q->where(fn($x)=>$x->where('title','like','%'.$s.'%')->orWhere('author','like','%'.$s.'%')->orWhere('isbn','like','%'.$s.'%')->orWhere('publisher','like','%'.$s.'%')->orWhere('sku','like','%'.$s.'%')); if($c=$d['category']??null)$q->whereHas('category',fn($x)=>$x->where('slug',$c)); match($d['sort']??'newest'){ 'price_asc'=>$q->orderBy('price'), 'price_desc'=>$q->orderByDesc('price'), 'bestseller'=>$q->orderByDesc('sold_count'), 'promo'=>$q->whereNotNull('discount_type')->orderByDesc('updated_at'), default=>$q->latest() }; return BookResource::collection($q->paginate($d['per_page']??12)); } public function show(Book $book) { abort_unless($book->is_active,404); $book->increment('views_count'); $book->loadAvg(['reviews' => fn($q) => $q->where('status', 'approved')], 'rating');
        return new BookResource($book->load(['category','images'])); } public function categories() { return response()->json(['data'=>Category::where('is_active',true)->orderBy('name')->get()]); } public function categoryBooks(Category $category,Request $r) { return BookResource::collection($category->books()->where('is_active',true)->withAvg(['reviews' => fn($q) => $q->where('status', 'approved')], 'rating')->paginate($r->integer('per_page',12))); } }
